START TRANSACTION;
INSERT INTO Branches(branch_name,ifsc_code,address,city,state,phone) VALUES('P2 synthetic','P2-TEST-IFSC','Synthetic','Test','Test','0000000090');
SET @p2_branch=LAST_INSERT_ID();
INSERT INTO Employees(branch_id,full_name,role,email,hire_date) VALUES(@p2_branch,'P2 synthetic teller','Teller','p2.teller@example.invalid','2020-01-01');
SET @p2_employee=LAST_INSERT_ID();
INSERT INTO Customers(full_name,dob,email,phone,address,id_proof_number,id_proof_type) VALUES('P2 synthetic','1990-01-01','p2.customer@example.invalid','0000000091','Synthetic','P2-SYNTHETIC-ID','Passport');
SET @p2_customer=LAST_INSERT_ID();
INSERT INTO Account_Types(type_name,interest_rate,min_balance) VALUES('P2 synthetic type',6.00,100.00);
SET @p2_type=LAST_INSERT_ID();
INSERT INTO Accounts(customer_id,branch_id,account_type_id,account_number,balance,opened_date) VALUES(@p2_customer,@p2_branch,@p2_type,'P2-SYNTHETIC-A',1000,'2026-01-01');
SET @p2_account=LAST_INSERT_ID();
CALL bank_lab.sp_expect_error(DATABASE(),'minimum decrease rejected','UPDATE {db}.Accounts SET balance=99 WHERE account_id=@p2_account',5015);
CALL bank_lab.sp_expect_ok(DATABASE(),'minimum boundary allowed','UPDATE {db}.Accounts SET balance=100 WHERE account_id=@p2_account');
CALL bank_lab.sp_expect_error(DATABASE(),'zero active rejected','UPDATE {db}.Accounts SET balance=0 WHERE account_id=@p2_account',5015);
INSERT INTO Accounts(customer_id,branch_id,account_type_id,account_number,balance,opened_date) VALUES(@p2_customer,@p2_branch,@p2_type,'P2-BELOW-MIN',1,'2026-01-01');
SET @p2_below=LAST_INSERT_ID();
CALL bank_lab.sp_expect_ok(DATABASE(),'increase below minimum allowed','UPDATE {db}.Accounts SET balance=50 WHERE account_id=@p2_below');
CALL bank_lab.sp_expect_error(DATABASE(),'decrease while already below minimum','UPDATE {db}.Accounts SET balance=25 WHERE account_id=@p2_below',5015);
CALL bank_lab.sp_expect_ok(DATABASE(),'settle zero and close together','UPDATE {db}.Accounts SET balance=0,status=''Closed'' WHERE account_id=@p2_below');
CALL bank_lab.sp_expect_error(DATABASE(),'closed balance immutable','UPDATE {db}.Accounts SET balance=200 WHERE account_id=@p2_below',5011);
CALL bank_lab.sp_expect_error(DATABASE(),'closed status terminal','UPDATE {db}.Accounts SET status=''Active'' WHERE account_id=@p2_below',5011);
CALL bank_lab.sp_expect_ok(DATABASE(),'closed no-op balance allowed','UPDATE {db}.Accounts SET balance=0 WHERE account_id=@p2_below');
INSERT INTO Customers(full_name,dob,email,phone,address,id_proof_number,id_proof_type) VALUES('P2 device other','1990-01-01','p2.device@example.invalid','0000000092','Synthetic','P2-SYNTHETIC-OTHER','Passport');
SET @p2_other_customer=LAST_INSERT_ID();
INSERT INTO Devices(customer_id,device_fingerprint,device_type,first_seen_at,last_seen_at) VALUES(@p2_other_customer,SHA2('p2-other',256),'Synthetic',NOW(),NOW());
SET @p2_bad_device=LAST_INSERT_ID();
INSERT INTO Devices(customer_id,device_fingerprint,device_type,first_seen_at,last_seen_at) VALUES(@p2_customer,SHA2('p2-owner',256),'Synthetic',NOW(),NOW());
SET @p2_device=LAST_INSERT_ID();
CALL bank_lab.sp_expect_error(DATABASE(),'device belongs to other customer','INSERT INTO {db}.Transactions(account_id,transaction_type,amount,balance_after,channel,status,reference_no,device_id) VALUES(@p2_account,''Deposit'',1,1001,''Online'',''Completed'',''P2-BAD-DEVICE'',@p2_bad_device)',5014);
CALL bank_lab.sp_expect_ok(DATABASE(),'device belongs to account owner','INSERT INTO {db}.Transactions(account_id,transaction_type,amount,balance_after,channel,status,reference_no,device_id) VALUES(@p2_account,''Deposit'',1,1001,''Online'',''Completed'',''P2-GOOD-DEVICE'',@p2_device)');
SET @p2_txn=(SELECT transaction_id FROM Transactions WHERE reference_no='P2-GOOD-DEVICE');
CALL bank_lab.sp_expect_error(DATABASE(),'ledger UPDATE immutable','UPDATE {db}.Transactions SET amount=2 WHERE transaction_id=@p2_txn',5012);
CALL bank_lab.sp_expect_error(DATABASE(),'ledger DELETE immutable','DELETE FROM {db}.Transactions WHERE transaction_id=@p2_txn',5012);
CALL bank_lab.sp_expect_error(DATABASE(),'self counterparty','INSERT INTO {db}.Transactions(account_id,transaction_type,amount,balance_after,channel,status,reference_no,related_account_id) VALUES(@p2_account,''Deposit'',1,1001,''Online'',''Completed'',''P2-SELF'',@p2_account)',5005);
CALL bank_lab.sp_expect_ok(DATABASE(),'NULL device accepted','INSERT INTO {db}.Transactions(account_id,transaction_type,amount,balance_after,channel,status,reference_no) VALUES(@p2_account,''Deposit'',1,1001,''Online'',''Completed'',''P2-NULL-DEVICE'')');
SET @p2_audit=(SELECT MAX(audit_id) FROM Audit_Log WHERE table_name='Transactions' AND record_pk=CAST(@p2_txn AS CHAR));
CALL bank_lab.sp_expect_error(DATABASE(),'audit UPDATE immutable','UPDATE {db}.Audit_Log SET record_pk=''changed'' WHERE audit_id=@p2_audit',5013);
CALL bank_lab.sp_expect_error(DATABASE(),'audit DELETE immutable','DELETE FROM {db}.Audit_Log WHERE audit_id=@p2_audit',5013);
ROLLBACK;
